    }

    /// Gets a storage value by key.
    ///
    /// # Examples
    /// ```
    /// # use stylus_test::TestVM;
    /// # use alloy_primitives::{B256, U256};
    /// let vm = TestVM::new();
    /// let key = U256::from(1);
    /// let value = vm.get_storage(key);
    /// assert_eq!(value, B256::ZERO);
