49	    /// Sets `token_uri` as the token URI of `token_id`.
50	    ///
51	    /// # Arguments
52	    ///
53	    /// * `&mut self` - Write access to the contract's state.
54	    /// * `token_id` - Id of a token.
55	    /// * `token_uri` - URI for the token.
56	    ///
57	    /// # Events
58	    ///
59	    /// * [`MetadataUpdate`].
60	    pub fn _set_token_uri(&mut self, token_id: U256, token_uri: String) {
61	        self.token_uris.setter(token_id).set_str(token_uri);
62	        self.vm().log(MetadataUpdate { token_id });
