70	        erc721: &impl IErc721<Error = erc721::Error>,
71	        metadata: &Erc721Metadata,
72	    ) -> Result<String, erc721::Error> {
73	        erc721.owner_of(token_id)?;
74	
75	        let token_uri = self.token_uris.getter(token_id).get_string();
76	        let base = metadata.base_uri();
77	
78	        // If there is no base URI, return the token URI.
79	        if base.is_empty() {
80	            return Ok(token_uri);
81	        }
82	
83	        // If both are set, concatenate the `base_uri` and `token_uri`.
84	        let uri = if token_uri.is_empty() {
85	            metadata.token_uri(token_id, erc721)?
86	        } else {
87	            base + &token_uri
88	        };
89	
90	        Ok(uri)
91	    }
