16	/// State of an [`Erc721Metadata`] contract.
17	#[storage]
18	pub struct Erc721Metadata {
19	    /// [`Metadata`] contract.
20	    pub(crate) metadata: Metadata,
21	    // TODO: Remove this field once function overriding is possible. For now we
22	    // keep this field `pub`, since this is used to simulate overriding.
23	    /// Base URI for tokens.
24	    pub base_uri: StorageString}
25	
26	/// Interface for the optional metadata functions from the ERC-721 standard.
27	#[interface_id]
28	#[public]
29	pub trait IErc721Metadata: IErc165 {
30	    /// The error type associated to this trait implementation.
31	    type Error: Into<alloc::vec::Vec<u8>>;
32	
33	    /// Returns the token collection name.
34	    ///
35	    /// # Arguments
36	    ///
37	    /// * `&self` - Read access to the contract's state.
38	    fn name(&self) -> String;
39	
40	    /// Returns token collection symbol.
41	    ///
42	    /// # Arguments
43	    ///
44	    /// * `&self` - Read access to the contract's state.
45	    fn symbol(&self) -> String;
46	
47	    /// Returns the Uniform Resource Identifier (URI) for `token_id` token.
48	    ///
49	    /// NOTE: The implementation should use `#[selector(name = "tokenURI")]` to
50	    /// match Solidity's camelCase naming convention.
51	    ///
52	    /// # Arguments
53	    ///
54	    /// * `&self` - Read access to the contract's state.
55	    /// * `token_id` - ID of a token.
56	    ///
57	    /// # Errors
58	    ///
59	    /// * [`erc721::Error::NonexistentToken`] - If the token does not exist.
60	    #[selector(name = "tokenURI")]
61	    fn token_uri(&self, token_id: U256) -> Result<String, Self::Error>;
62	}
63	
64	impl Erc721Metadata {
65	    /// Constructor.
66	    ///
67	    /// # Arguments
68	    ///
69	    /// * `&mut self` - Write access to the contract's state.
70	    /// * `name` - Token name.
71	    /// * `symbol` - Token symbol.
72	    pub fn constructor(&mut self, name: String, symbol: String) {
73	        self.metadata.constructor(name, symbol);
74	    }
75	
76	    /// Check [`IErc721Metadata::name()`] for more details.
77	    pub fn name(&self) -> String {
78	        self.metadata.name()
79	    }
80	
81	    /// Check [`IErc721Metadata::symbol()`] for more details.
82	    pub fn symbol(&self) -> String {
83	        self.metadata.symbol()
84	    }
85	
86	    /// Returns the base of Uniform Resource Identifier (URI) for tokens'
87	    /// collection.
88	    ///
89	    /// # Arguments
90	    ///
91	    /// * `&self` - Read access to the contract's state.
92	    pub fn base_uri(&self) -> String {
93	        self.base_uri.get_string()
94	    }
95	
96	    /// Check [`IErc721Metadata::token_uri()`] for more details.
97	    #[allow(clippy::missing_errors_doc)]
98	    pub fn token_uri(
99	        &self,
100	        token_id: U256,
101	        erc721: &impl IErc721<Error = erc721::Error>,
102	    ) -> Result<String, erc721::Error> {
103	        erc721.owner_of(token_id)?;
104	
105	        let base_uri = self.base_uri();
106	
107	        let token_uri = if base_uri.is_empty() {
108	            String::new()
109	        } else {
110	            base_uri + &token_id.to_string()
111	        };
112	
113	        Ok(token_uri)
114	    }
115	}
