1	//! ERC-721 token with storage-based token URI management.
2	//!
3	//! It also implements IERC4096, which is an ERC-721 Metadata Update Extension.
4	use alloc::{string::String, vec, vec::Vec};
5	
6	use alloy_primitives::U256;
7	pub use sol::*;
8	use stylus_sdk::{prelude::*, storage::{StorageMap, StorageString}};
9	
10	use crate::token::erc721::{
11	    self,
12	    extensions::{Erc721Metadata, IErc721Metadata},
13	    IErc721};
14	
15	#[cfg_attr(coverage_nightly, coverage(off))]
16	mod sol {
17	    use alloy_sol_macro::sol;
18	
19	    sol! {
20	        /// This event gets emitted when the metadata of a token is changed.
21	        ///
22	        /// The event comes from IERC4096.
23	        #[derive(Debug)]
24	        #[allow(missing_docs)]
25	        event MetadataUpdate(uint256 token_id);
26	
27	        /// This event gets emitted when the metadata of a range of tokens
28	        /// is changed.
29	        ///
30	        /// The event comes from IERC4096.
31	        #[derive(Debug)]
32	        #[allow(missing_docs)]
33	        event BatchMetadataUpdate(uint256 from_token_id, uint256 to_token_id);
34	    }
35	}
36	
37	/// State of an [`Erc721UriStorage`] contract.
38	#[storage]
39	pub struct Erc721UriStorage {
40	    /// Optional mapping for token URIs.
41	    pub token_uris: StorageMap<U256, StorageString>}
42	
43	/// Interface of an optional extension ERC-721 token providing storage based
44	/// token URI management.
45	#[public]
46	pub trait IErc721UriStorage: IErc721Metadata {}
47	
48	impl Erc721UriStorage {
49	    /// Sets `token_uri` as the token URI of `token_id`.
50	    ///
51	    /// # Arguments
52	    ///
53	    /// * `&mut self` - Write access to the contract's state.
54	    /// * `token_id` - Id of a token.
55	    /// * `token_uri` - URI for the token.
56	    ///
57	    /// # Events
58	    ///
59	    /// * [`MetadataUpdate`].
60	    pub fn _set_token_uri(&mut self, token_id: U256, token_uri: String) {
61	        self.token_uris.setter(token_id).set_str(token_uri);
62	        self.vm().log(MetadataUpdate { token_id });
63	    }
64	
65	    /// Check [`IErc721Metadata::token_uri()`] for more details.
66	    #[allow(clippy::missing_errors_doc)]
67	    pub fn token_uri(
68	        &self,
69	        token_id: U256,
70	        erc721: &impl IErc721<Error = erc721::Error>,
71	        metadata: &Erc721Metadata,
72	    ) -> Result<String, erc721::Error> {
73	        erc721.owner_of(token_id)?;
74	
75	        let token_uri = self.token_uris.getter(token_id).get_string();
76	        let base = metadata.base_uri();
77	
78	        // If there is no base URI, return the token URI.
79	        if base.is_empty() {
80	            return Ok(token_uri);
81	        }
82	
83	        // If both are set, concatenate the `base_uri` and `token_uri`.
84	        let uri = if token_uri.is_empty() {
85	            metadata.token_uri(token_id, erc721)?
86	        } else {
87	            base + &token_uri
88	        };
89	
90	        Ok(uri)
91	    }
92	}
