    };

    const TOKEN_ID: U256 = uint!(1_U256);

    #[test]
    fn burns() {
        let vm = TestVM::default();
        let mut contract = Erc721::from(&vm);
        let one = uint!(1_U256);

vm.set_sender(ALICE);
                contract
            ._mint(ALICE, TOKEN_ID)
            .expect("should mint a token for Alice");

        let initial_balance = contract
            .balance_of(ALICE)
            .expect("should return the balance of Alice");

        let result = contract.burn(TOKEN_ID);
        assert!(result.is_ok());

        let balance = contract
            .balance_of(ALICE)
            .expect("should return the balance of Alice");

        assert_eq!(initial_balance - one, balance);

        let err = contract
            .owner_of(TOKEN_ID)
            .expect_err("should return Error::NonexistentToken");

        assert!(matches!(
            err,
            Error::NonexistentToken (ERC721NonexistentToken{
                token_id: t_id
            }) if t_id == TOKEN_ID
        ));
    }

    #[test]
    fn burns_with_approval() {
        let vm = TestVM::default();
        let mut contract = Erc721::from(&vm);
vm.set_sender(ALICE);
                contract
            ._mint(BOB, TOKEN_ID)
            .expect("should mint a token for Bob");

        let initial_balance = contract
            .balance_of(BOB)
            .expect("should return the balance of Bob");

vm.set_sender(BOB);
                contract
            .approve(ALICE, TOKEN_ID)
            .expect("should approve a token for Alice");

vm.set_sender(ALICE);
                let result = contract.burn(TOKEN_ID);
        assert!(result.is_ok());

        let err = contract
            .owner_of(TOKEN_ID)
            .expect_err("should return Error::NonexistentToken");

        assert!(matches!(
            err,
            Error::NonexistentToken (ERC721NonexistentToken{
                token_id: t_id
            }) if t_id == TOKEN_ID
        ));

        let balance = contract
            .balance_of(BOB)
            .expect("should return the balance of Bob");

        assert_eq!(initial_balance - uint!(1_U256), balance);
    }

    #[test]
