#!/usr/bin/env python3
"""Compare original (motsu) and converted (TestVM) test bodies after normalization.

usage: verify_conversion.py BASE_REV
Compares every test function of the erc721 files that exist in both versions.
"""
import re
import subprocess
import sys

BASE = sys.argv[1]
ROOT = "/tmp/bench/wt/erc721"
FILES = [
    "contracts/src/token/erc721/mod.rs",
    "contracts/src/token/erc721/extensions/burnable.rs",
    "contracts/src/token/erc721/extensions/consecutive.rs",
    "contracts/src/token/erc721/extensions/enumerable.rs",
    "contracts/src/token/erc721/extensions/metadata.rs",
    "contracts/src/token/erc721/extensions/uri_storage.rs",
    "contracts/src/token/erc721/extensions/wrapper.rs",
    "contracts/src/token/erc721/utils/holder.rs",
]
ACCOUNTS = {"alice": "ALICE", "bob": "BOB", "charlie": "CHARLIE", "dave": "DAVE"}


def segments(text):
    """Yield (kind, chunk) with kind in code|string|comment."""
    i, n = 0, len(text)
    start = 0
    while i < n:
        c = text[i]
        if c == '"':
            if start < i:
                yield "code", text[start:i]
            j = i + 1
            while j < n:
                if text[j] == "\\":
                    j += 2
                    continue
                if text[j] == '"':
                    j += 1
                    break
                j += 1
            yield "string", text[i:j]
            i = start = j
        elif text.startswith("//", i):
            if start < i:
                yield "code", text[start:i]
            j = text.find("\n", i)
            j = n if j < 0 else j
            yield "comment", text[i:j]
            i = start = j
        else:
            i += 1
    if start < n:
        yield "code", text[start:]


def mask(text):
    out = []
    for kind, chunk in segments(text):
        if kind == "code":
            out.append(chunk)
        else:
            out.append(re.sub(r"[^\n]", " ", chunk))
    return "".join(out)


def find_close(masked, open_idx):
    depth = 0
    for i in range(open_idx, len(masked)):
        if masked[i] == "{":
            depth += 1
        elif masked[i] == "}":
            depth -= 1
            if depth == 0:
                return i
    raise ValueError


def tests_of(text):
    idx = text.index("#[cfg(test)]")
    region = text[idx:]
    masked = mask(region)
    found = {}
    for m in re.finditer(r"#\[(?:motsu::)?test\]((?:\s*#\[[^\]]*\])*)\s*fn (\w+)\([^)]*\)\s*\{", masked):
        name = m.group(2)
        open_idx = m.end() - 1
        close_idx = find_close(masked, open_idx)
        found[name] = region[open_idx + 1:close_idx]
    return found


def normalize(body, original):
    parts = []
    for kind, chunk in segments(body):
        if kind == "comment":
            continue
        if kind == "code":
            if original:
                chunk = re.sub(r"\.sender\(\w+\)", "", chunk)
                chunk = re.sub(r"\b(alice|bob|charlie|dave)\b", lambda m: ACCOUNTS[m.group(1)], chunk)
            else:
                chunk = re.sub(r"vm\.set_sender\([^;]*\);", "", chunk)
                chunk = re.sub(r"let vm = TestVM::default\(\);", "", chunk)
                chunk = re.sub(r"let (mut )?contract = \w+::from\(&vm\);", "", chunk)
        parts.append(chunk)
    s = "".join(parts)
    s = re.sub(r"\s+", "", s)
    s = re.sub(r",([)\]}])", r"\1", s)
    s = s.replace("motsu_", "")
    return s


def show(path, rev):
    if rev == "WORKTREE":
        return open(f"{ROOT}/{path}").read()
    return subprocess.check_output(["git", "-C", ROOT, "show", f"{rev}:{path}"], text=True)


total = same = 0
for f in FILES:
    old = tests_of(show(f, BASE))
    new = tests_of(show(f, "WORKTREE"))
    missing = sorted(set(old) - set(new))
    extra = sorted(set(new) - set(old))
    diff = []
    for name in sorted(set(old) & set(new)):
        total += 1
        if normalize(old[name], True) == normalize(new[name], False):
            same += 1
        else:
            diff.append(name)
    print(f"{f}: {len(old)} before, {len(new)} after, missing={missing}, extra={extra}")
    for d in diff:
        print(f"    DIFFERS (needs manual review): {d}")
print(f"identical after normalization: {same}/{total}")

