#!/usr/bin/env python3
"""cut_tests.py FILE NAME... : print FILE with the named #[test] fns removed (to stdout);
   the removed text is written to FILE.cut.txt next to /tmp/bench/scratch."""
import re, sys
sys.path.insert(0, '/tmp/bench/scratch')
path, names = sys.argv[1], sys.argv[2:]
text = open(path).read()

def mask(t):
    out = []; i = 0; n = len(t)
    while i < n:
        c = t[i]
        if c == '"':
            out.append('"'); i += 1
            while i < n:
                if t[i] == '\\': out.append('  '); i += 2; continue
                if t[i] == '"': out.append('"'); i += 1; break
                out.append('\n' if t[i] == '\n' else ' '); i += 1
        elif t.startswith('//', i):
            while i < n and t[i] != '\n': out.append(' '); i += 1
        else:
            out.append(c); i += 1
    return ''.join(out)

removed = []
for name in names:
    m = mask(text)
    mm = re.search(r'    #\[test\]\n    fn ' + re.escape(name) + r'\(\) \{', m)
    assert mm, name
    start = mm.start()
    depth = 0
    for i in range(mm.end() - 1, len(m)):
        if m[i] == '{': depth += 1
        elif m[i] == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                break
    # also swallow the following blank line
    if text[end:end+2] == '\n\n':
        end += 2
    elif text[end:end+1] == '\n':
        end += 1
    removed.append(text[start:end])
    text = text[:start] + text[end:]
open('/tmp/bench/scratch/cut.txt', 'w').write(''.join(removed))
sys.stdout.write(text)
EOF
